#include <iostream>

int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int* p = arr;
    p++;
    std::cout << *p << " ";
    *p = *p + 5;
    std::cout << *(p + 1) << " ";
    std::cout << arr[1];
    return 0;
}

#include <iostream>

int main() {
    int a = 5;
    int b = 10;
    int& ref = a;
    ref = b;
    b = 20;
    std::cout << a << " " << ref;
    return 0;
}

#include <iostream>

void modify(int** p) {
    int static x = 100;
    *p = &x;
}

int main() {
    int a = 10;
    int* ptr = &a;
    modify(&ptr);
    std::cout << *ptr;
    return 0;
}
